head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


scwin.gPvd;
scwin.gGridNewYn;
scwin.gExcptTpCd;
scwin.gSeq;
scwin.gIsurCd;
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.fn_getParam = function() {
    var pvd = scwin.fn_GetProvider();
    var Temp0 = pvd.split("&")[1];
    var Temp1 = pvd.split("&")[2];
    var Temp2 = pvd.split("&")[3];
    var Temp3 = pvd.split("&")[4];
    var Temp4 = pvd.split("&")[5];
    //alert(pvd +' / '+ Temp0  +' / '+  Temp1 +' / '+ Temp2);

    scwin.gSeq = Temp0.split("=")[1];
    scwin.gIsurCd = Temp1.split("=")[1];
    scwin.gGridNewYn = Temp2.split("=")[1];
    scwin.gExcptTpCd = Temp3.split("=")[1];
    scwin.gPvd = Temp4.split("=")[1];
    //alert('gAcptNo='+gAcptNo);
    //alert('gPvd='+gPvd);

};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};


// 화면닫기
scwin.fn_CloseWin = async function() {
    await $c.frame.CloseFrame();
};
scwin.fn_PvdSearch = function() {
    $c.frame.path("../" + scwin.gPvd).fn_Search();
};
